// Diagnostics only: count transient database failures without retaining SQL,
// arguments, credentials or error details from the runtime connection.
type iamTransactionFailureTrace struct {
	serialization atomic.Int64
	deadlock      atomic.Int64
	lastSQLState  atomic.Value // SQLSTATE only, never a database message or arguments.
}

func (*iamTransactionFailureTrace) TraceQueryStart(ctx context.Context, _ *pgx.Conn, _ pgx.TraceQueryStartData) context.Context {
	return ctx
}

func (trace *iamTransactionFailureTrace) TraceQueryEnd(_ context.Context, _ *pgx.Conn, data pgx.TraceQueryEndData) {
	var databaseError *pgconn.PgError
	if errors.As(data.Err, &databaseError) {
		trace.lastSQLState.Store(databaseError.Code)
		switch databaseError.Code {
		case "40001":
			trace.serialization.Add(1)
		case "40P01":
			trace.deadlock.Add(1)
		}
	}
}

// Only encrypted completion commitments for one synthetic request are retained.
// This proves real Serializable retry reuse without adding a production cipher
// hook or logging SQL, credentials, raw material or unrelated query arguments.
type iamAccessKeyCompletionTrace struct {
	*iamTransactionFailureTrace
	requestID string
	mu        sync.Mutex
	invalid   bool
	attempts  []struct {
		KeyID    iamv1.AccessKeyID
		Format   uint8
		Material [32]byte
	}
}

func (trace *iamAccessKeyCompletionTrace) TraceQueryStart(ctx context.Context, _ *pgx.Conn, data pgx.TraceQueryStartData) context.Context {
	if !strings.HasPrefix(data.SQL, "SELECT iam.complete_access_key(") || len(data.Args) != 10 {
		return ctx
	}
	encoded, ok := data.Args[9].([]byte)
	var event auditv1.Event
	requestID := trace.requestID
	if requestID == "" {
		requestID = "key-first"
	}
	if !ok || json.Unmarshal(encoded, &event) != nil || event.RequestID != requestID {
		return ctx
	}
	trace.mu.Lock()
	defer trace.mu.Unlock()
	id, idOK := data.Args[5].(iamv1.AccessKeyID)
	format, formatOK := data.Args[6].(uint8)
	nonce, nonceOK := data.Args[7].([]byte)
	ciphertext, ciphertextOK := data.Args[8].([]byte)
	if !idOK || !formatOK || !nonceOK || !ciphertextOK || len(nonce) != 12 || len(ciphertext) != 48 || len(trace.attempts) >= 5 {
		trace.invalid = true
		return ctx
	}
	material := append(bytes.Clone(nonce), ciphertext...)
	trace.attempts = append(trace.attempts, struct {
		KeyID    iamv1.AccessKeyID
		Format   uint8
		Material [32]byte
	}{id, format, sha256.Sum256(material)})
	clear(material)
	return ctx
}

// Wait until two real decisions hold actor foreign-key references before
// releasing their writers. Shared advisory locks do not serialize the writers
// themselves; only the production identity/target locks may do that.
func holdRecordedIdentityDecisions(t *testing.T, ctx context.Context, database *pgx.Conn, first, second string) func() {
	t.Helper()
	if first == second || iamv1.ValidateID("requestId", first) != nil || iamv1.ValidateID("requestId", second) != nil {
		t.Fatal("invalid recorded identity barrier requests")
	}
	if _, err := database.Exec(ctx, `CREATE FUNCTION public.matrix_recorded_identity_barrier() RETURNS trigger LANGUAGE plpgsql AS $body$
	 BEGIN IF NEW.event_document->>'action'='iam.authorization.decided' AND NEW.event_document->>'requestId' IN (TG_ARGV[0],TG_ARGV[1])
	 THEN PERFORM pg_advisory_xact_lock_shared(54841,26); END IF; RETURN NEW; END $body$;
	 CREATE TRIGGER matrix_recorded_identity_barrier BEFORE INSERT ON iam.audit_outbox
	 FOR EACH ROW EXECUTE FUNCTION public.matrix_recorded_identity_barrier('`+first+`','`+second+`'); SELECT pg_advisory_lock(54841,26)`); err != nil {
		t.Fatal("install recorded identity barrier", err)
	}
	t.Cleanup(func() {
		cleanup, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if _, err := database.Exec(cleanup, `SELECT pg_advisory_unlock(54841,26);
		 DROP TRIGGER IF EXISTS matrix_recorded_identity_barrier ON iam.audit_outbox;
		 DROP FUNCTION IF EXISTS public.matrix_recorded_identity_barrier()`); err != nil {
			t.Error("remove recorded identity barrier", err)
		}
	})
	return func() {
		t.Helper()
		blocked, cancel := context.WithTimeout(ctx, 5*time.Second)
		defer cancel()
		ticker := time.NewTicker(10 * time.Millisecond)
		defer ticker.Stop()
		for waiting := 0; waiting != 2; {
			if err := database.QueryRow(blocked, `SELECT count(*) FROM pg_locks WHERE locktype='advisory' AND NOT granted
			 AND database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND classid=54841 AND objid=26`).Scan(&waiting); err != nil {
				t.Fatal("observe both recorded identities before writes", err)
			}
			if waiting != 2 {
				select {
				case <-ticker.C:
				case <-blocked.Done():
					t.Fatal("both transactions did not reach recorded identity references")
				}
			}
		}
		if _, err := database.Exec(ctx, `SELECT pg_advisory_unlock(54841,26)`); err != nil {
			t.Fatal(err)
		}
	}
}

// Stop one real IAM request either after evaluation (before the decision FK),
// or after its material/locks exist but before commit. The peer command is
// never paused by this fixture; production row locks must order the effects.
func holdIAMRequest(t *testing.T, ctx context.Context, database *pgx.Conn, requestID string, afterWrite bool, action auditv1.Action) (func() int32, func()) {
	t.Helper()
	if iamv1.ValidateID("requestId", requestID) != nil || (afterWrite && iamv1.ValidateID("action", string(action)) != nil) {
		t.Fatal("invalid IAM barrier intent")
	}
	table, condition := "iam.authorization_decisions", "NEW.request_id=TG_ARGV[0]"
	if afterWrite {
		table, condition = "iam.audit_outbox", "NEW.event_document->>'requestId'=TG_ARGV[0] AND NEW.event_document->>'action'=TG_ARGV[1]"
	}
	if _, err := database.Exec(ctx, `CREATE FUNCTION public.matrix_key_linearization() RETURNS trigger LANGUAGE plpgsql AS $body$
	 BEGIN IF `+condition+` THEN PERFORM pg_advisory_xact_lock_shared(54854,29); END IF; RETURN NEW; END $body$;
	 CREATE TRIGGER matrix_key_linearization BEFORE INSERT ON `+table+` FOR EACH ROW EXECUTE FUNCTION public.matrix_key_linearization('`+requestID+`','`+string(action)+`');
	 SELECT pg_advisory_lock(54854,29)`); err != nil {
		t.Fatal("install key linearization barrier", err)
	}
	var once sync.Once
	release := func() {
		once.Do(func() {
			cleanup, stop := context.WithTimeout(context.Background(), 5*time.Second)
			defer stop()
			if _, err := database.Exec(cleanup, "SELECT pg_advisory_unlock(54854,29)"); err != nil {
				t.Error("release key linearization barrier", err)
			}
		})
	}
	t.Cleanup(func() {
		release()
		cleanup, stop := context.WithTimeout(context.Background(), 5*time.Second)
		defer stop()
		if _, err := database.Exec(cleanup, `DROP TRIGGER IF EXISTS matrix_key_linearization ON `+table+`; DROP FUNCTION IF EXISTS public.matrix_key_linearization()`); err != nil {
			t.Error("remove key linearization barrier", err)
		}
	})
	return func() int32 {
		t.Helper()
		wait, stop := context.WithTimeout(ctx, 5*time.Second)
		defer stop()
		ticker := time.NewTicker(10 * time.Millisecond)
		defer ticker.Stop()
		for {
			var pid int32
			if err := database.QueryRow(wait, `SELECT COALESCE(min(pid),0) FROM pg_locks WHERE locktype='advisory' AND NOT granted
			 AND database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND classid=54854 AND objid=29`).Scan(&pid); err != nil {
				t.Fatal("observe actual key barrier", err)
			}
			if pid != 0 {
				return pid
			}
			select {
			case <-ticker.C:
			case <-wait.Done():
				t.Fatal("key request never reached its linearization barrier")
			}
		}
	}, release
}

func findIAMCapability(values []iamv1.ActionCapability, action iamv1.Action, kind iamv1.ResourceKind, id string) (iamv1.ActionCapability, bool) {
	for _, value := range values {
		if value.Action == action && value.Resource.Kind == kind && value.Resource.ID == id {
			return value, true
		}
	}
	return iamv1.ActionCapability{}, false
}

